#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

// Run from the pack or the project, or from any folder by its path: without docs/gates.md here, the pack is the root
const ROOT = fs.existsSync(path.join(process.cwd(), 'docs', 'gates.md'))
  ? process.cwd()
  : path.resolve(import.meta.dirname, '..');
const GATES = path.join(ROOT, 'docs', 'gates.md');
const RULES_DIR = path.join(ROOT, '.claude', 'rules');
const SKILLS_DIR = path.join(ROOT, '.claude', 'skills');
const OUTPUT = path.join(ROOT, 'docs', 'canon.md');

const FIRST_LINE =
  'Generated by scripts/gen-canon.mjs from docs/gates.md, the rule files it names and .claude/skills: edit those, then run pnpm canon.';
const INTRO = 'Read this first: one line per rule of the canon; a rule checked by review has no gate yet.';
const HEADER = ['Rule', 'Written in', 'Checked by', 'Applied by'];
const NO_SKILLS = '—';
const REVIEW = '`review`';
const WRITTEN_IN = /`([\w.-]+\.md) §(\d+)`/g;
const SECTION_HEADING = /^## (\d+)\. (.+)$/gm;
const BACKTICKED = /`([^`]+)`/g;
const RULE_ID = /^[@\w][\w@/-]*$/;

class CanonError extends Error {}

const readText = (file) => fs.readFileSync(file, 'utf8').replaceAll('\r\n', '\n');

// A cell ends at a pipe that is not escaped as \|.
const splitRow = (line) =>
  line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split(/(?<!\\)\|/)
    .map((cell) => cell.trim());

const isSeparator = (cells) => cells.every((cell) => /^:?-+:?$/.test(cell));

// The rows of the first table whose header holds every name, each row keyed by the header names.
const readTable = (text, names) => {
  const lines = text.split('\n');
  const headerAt = lines.findIndex(
    (line) => line.trim().startsWith('|') && names.every((name) => splitRow(line).includes(name)),
  );
  if (headerAt === -1) return null;
  const columns = splitRow(lines[headerAt] ?? '');
  const rows = [];
  for (const line of lines.slice(headerAt + 1)) {
    if (!line.trim().startsWith('|')) break;
    const cells = splitRow(line);
    if (isSeparator(cells)) continue;
    rows.push(Object.fromEntries(columns.map((column, index) => [column, cells[index] ?? ''])));
  }
  return rows;
};

const readSections = (text) => {
  const headings = [...text.matchAll(SECTION_HEADING)];
  return headings.map((heading, index) => ({
    number: Number(heading[1]),
    title: (heading[2] ?? '').trim(),
    body: text.slice(heading.index + heading[0].length, headings[index + 1]?.index ?? text.length),
  }));
};

const readRuleFile = (file) => {
  const rulePath = path.join(RULES_DIR, file);
  return fs.existsSync(rulePath) ? readSections(readText(rulePath)) : null;
};

const readSkills = () =>
  fs.existsSync(SKILLS_DIR)
    ? fs
        .readdirSync(SKILLS_DIR, { withFileTypes: true })
        .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(SKILLS_DIR, entry.name, 'SKILL.md')))
        .map((entry) => ({ name: entry.name, text: readText(path.join(SKILLS_DIR, entry.name, 'SKILL.md')) }))
    : [];

const escapeRegExp = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);

const ruleIdsOf = (checkedBy) =>
  [...checkedBy.matchAll(BACKTICKED)].map((match) => match[1] ?? '').filter((span) => RULE_ID.test(span));

const namesSection = (text, file, number) => new RegExp(`${escapeRegExp(file)}\`?\\s*§${number}(?!\\d)`).test(text);

const appliedBy = (skills, line) => {
  const ids = line.isReview ? [] : ruleIdsOf(line.checkedBy);
  const names = skills
    .filter(
      (skill) => namesSection(skill.text, line.file, line.number) || ids.some((id) => skill.text.includes(`\`${id}\``)),
    )
    .map((skill) => `\`${skill.name}\``)
    .sort();
  return names.length > 0 ? names.join(', ') : NO_SKILLS;
};

// The gates rows with their one `FILE §N`; a row without it or with a wrong one is a problem.
const readGateRows = (problems) => {
  const rows = readTable(readText(GATES), ['Rule', 'Checked by']);
  if (rows === null) throw new CanonError('docs/gates.md has no table with the columns Rule and Checked by');
  const sections = new Map();
  return rows.flatMap((row) => {
    const label = `docs/gates.md: the row "${(row.Rule ?? '').slice(0, 70)}"`;
    const refs = [...(row['Written in'] ?? '').matchAll(WRITTEN_IN)];
    if (refs.length !== 1) {
      problems.push(`${label} needs one \`FILE §N\` in Written in, it has ${refs.length}`);
      return [];
    }
    const file = refs[0]?.[1] ?? '';
    const number = Number(refs[0]?.[2]);
    if (!sections.has(file)) sections.set(file, readRuleFile(file));
    const fileSections = sections.get(file);
    if (!fileSections) {
      problems.push(`${label} names the missing rule file ${file}`);
      return [];
    }
    if (!fileSections.some((section) => section.number === number)) {
      problems.push(`${label} names the missing section ${file} §${number}`);
      return [];
    }
    return [{ file, number, rule: row.Rule ?? '', checkedBy: row['Checked by'] ?? '' }];
  });
};

const designRowsOf = (section) =>
  (readTable(section.body, ['Id', 'Rule', 'Checked by']) ?? []).map((row) => ({
    rule: `${row.Id}: ${row.Rule}`,
    checkedBy: row['Checked by'] ?? '',
  }));

// By rule file in the order of its first gates row, by section number; a section nothing names is a review row.
const buildLines = (gateRows) => {
  const files = [...new Set(gateRows.map((row) => row.file))];
  return files.flatMap((file) =>
    (readRuleFile(file) ?? []).flatMap((section) => {
      const own = [
        ...gateRows.filter((row) => row.file === file && row.number === section.number),
        ...designRowsOf(section),
      ];
      const rows = own.length > 0 ? own : [{ rule: section.title, checkedBy: REVIEW }];
      return rows.map((row) => ({ ...row, file, number: section.number, isReview: own.length === 0 }));
    }),
  );
};

const renderTable = (rows) => {
  const widths = HEADER.map((name, index) => Math.max(name.length, 3, ...rows.map((row) => row[index]?.length ?? 0)));
  const renderRow = (cells) => `| ${cells.map((cell, index) => cell.padEnd(widths[index] ?? 0)).join(' | ')} |`;
  return [
    renderRow(HEADER),
    `| ${widths.map((width) => '-'.repeat(width)).join(' | ')} |`,
    ...rows.map(renderRow),
  ].join('\n');
};

const build = () => {
  const problems = [];
  const gateRows = readGateRows(problems);
  if (problems.length > 0) throw new CanonError(problems.join('\n'));
  const skills = readSkills();
  const rows = buildLines(gateRows).map((line) => [
    line.rule,
    `\`${line.file} §${line.number}\``,
    line.checkedBy,
    appliedBy(skills, line),
  ]);
  return `${[FIRST_LINE, '', INTRO, '', renderTable(rows)].join('\n')}\n`;
};

const run = () => {
  const content = build();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(OUTPUT) ? readText(OUTPUT) : '';
    if (current === content) return 0;
    process.stderr.write('docs/canon.md is stale: run `pnpm canon` and commit the result.\n');
    return 1;
  }
  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, content);
  process.stdout.write('canon index → docs/canon.md\n');
  return 0;
};

try {
  process.exitCode = run();
} catch (error) {
  if (!(error instanceof CanonError)) throw error;
  process.stderr.write(`${error.message}\n`);
  process.exitCode = 1;
}
